\text{Area of } KLMN &= \frac{1}{2}(2 + 2\sqrt{3})^2\sqrt{3} \\
&= \frac{1}{2}(4 + 8\sqrt{3} + 12)\sqrt{3} \\
&= \frac{1}{2}(16 + 8\sqrt{3}) \\
&= \boxed{8 + 4\sqrt{3}}
\end{align}

